// Real photographs of Azadi Stadium (Wikimedia Commons, freely licensed), each tagged with
// where in the bowl it was taken. A seat is matched to the closest real viewpoint we have;
// the UI says so plainly instead of pretending it's the exact view from that seat.

import rawManifest from './photo-manifest.json'
import type { Section } from './stadium'

export type ViewpointId =
  | 'lower-side'
  | 'lower-front'
  | 'lower-corner'
  | 'end-lower-pano'
  | 'end-elevated'
  | 'upper-curve'
  | 'upper-corner'
  | 'upper-top-pano'

/** Generated by `npm run assets` (scripts/build-assets.mjs). */
export interface PhotoMeta {
  width: number
  height: number
  widths: number[]
  placeholder: string
  credit: { title: string; author: string; license: string; licenseUrl: string; page: string }
}
const manifest = rawManifest as Record<ViewpointId, PhotoMeta>

export interface Viewpoint {
  id: ViewpointId
  title: string
  where: string
  /** Panorama: wide image meant to be dragged horizontally. */
  panorama: boolean
  /** Initial horizontal focus (0 = left edge, 1 = right edge). */
  focus: number
}

export const VIEWPOINTS: Viewpoint[] = [
  { id: 'lower-side', title: 'کنار زمین، طبقهٔ پایین', where: 'ردیف‌های میانی طبقهٔ پایین، نزدیک خط میانه', panorama: false, focus: 0.45 },
  { id: 'lower-front', title: 'ردیف‌های جلو، کنار زمین', where: 'ردیف‌های اول طبقهٔ پایین، پشت حصار پیست', panorama: false, focus: 0.55 },
  { id: 'lower-corner', title: 'گوشه، طبقهٔ پایین', where: 'گوشهٔ طبقهٔ پایین، رو به طول زمین', panorama: false, focus: 1 },
  { id: 'end-lower-pano', title: 'پشت دروازه، طبقهٔ پایین', where: 'طبقهٔ پایین پشت دروازه — عکس پانوراما', panorama: true, focus: 0.52 },
  { id: 'end-elevated', title: 'پشت دروازه، از بالا', where: 'بالای سکوهای پشت دروازه، رو به کل زمین', panorama: false, focus: 0.5 },
  { id: 'upper-curve', title: 'قوس انتهایی، طبقهٔ بالا', where: 'طبقهٔ بالا در قوس انتهای ورزشگاه، رو به طول زمین', panorama: false, focus: 0.5 },
  { id: 'upper-corner', title: 'گوشه، طبقهٔ بالا', where: 'طبقهٔ بالا در گوشهٔ ورزشگاه، رو به قطر زمین', panorama: false, focus: 0.5 },
  { id: 'upper-top-pano', title: 'ردیف‌های آخر طبقهٔ بالا', where: 'بالاترین ردیف‌های طبقهٔ بالا — عکس پانوراما', panorama: true, focus: 0.45 },
]

export const VIEWPOINT_BY_ID = new Map(VIEWPOINTS.map((v) => [v.id, v]))

/** Corner section whose centre is closer to an end of the pitch than to a side. */
function nearEnd(s: Section) {
  const deg = ((((s.theta0 + s.theta1) / 2) * 180) / Math.PI + 360) % 360
  const toEnd = Math.min(deg, Math.abs(180 - deg), 360 - deg)
  return toEnd < 40
}

export function viewpointFor(section: Section, row: number): Viewpoint {
  const id: ViewpointId = (() => {
    if (section.tier === 'lower') {
      if (section.zone === 'halfway') return row <= 4 ? 'lower-front' : 'lower-side'
      if (section.zone === 'corner') return 'lower-corner'
      return row >= 11 ? 'end-elevated' : 'end-lower-pano'
    }
    if (section.zone === 'halfway') return row >= 12 ? 'upper-top-pano' : 'upper-corner'
    if (section.zone === 'corner') return nearEnd(section) ? 'upper-curve' : 'upper-corner'
    return 'end-elevated'
  })()
  return VIEWPOINT_BY_ID.get(id)!
}

export const photoMeta = (id: ViewpointId): PhotoMeta => manifest[id]

export function srcSet(id: ViewpointId, ext: 'avif' | 'webp') {
  return manifest[id].widths.map((w) => `/photos/${id}-${w}.${ext} ${w}w`).join(', ')
}
export const fallbackSrc = (id: ViewpointId) => {
  const ws = manifest[id].widths
  return `/photos/${id}-${ws[Math.min(1, ws.length - 1)]}.webp`
}
